  async initiate(params: InitiateParams, credentials: Credentials, _ctx?: GatewayContext): Promise<InitiateResult> {
    const apiKey = String(credentials["api_key"] ?? '');
    const method = String(credentials["method"] ?? '');
    const trxId = (params.trx_id ?? '');
    const amountValue = Number((params.amount ?? '')).toFixed(2);
    const currency = String((params.currency ?? '')).toUpperCase();
    const redirectUrl = (params.redirect_url ?? '');
    const payload: Record<string, unknown> = { ["amount"]: { ["currency"]: currency, ["value"]: amountValue }, ["description"]: `Payment ${String(trxId)}`, ["redirectUrl"]: redirectUrl, ["method"]: method, ["metadata"]: { ["trx_id"]: trxId } };
    const res = await gwJson({
      url: "https://api.mollie.com/v2/payments",
      method: 'POST',
      headers: { ["Content-Type"]: "application/json", ["Authorization"]: `Bearer ${String(apiKey)}` },
      body: JSON.stringify(payload),
      timeoutMs: 15000,
    });
    if (res.data === null) throw new Error(`${SLUG}: invalid response`);
    const d = res.data as Record<string, unknown>;
    const links = ((d) as Record<string, unknown>)["_links"] ?? {};
    const checkout = ((links) as Record<string, unknown>)["checkout"] ?? {};
    const checkoutUrl = String(((checkout) as Record<string, unknown>)["href"] ?? '');
    const sessionId = String(((d) as Record<string, unknown>)["id"] ?? '');
    return {
          redirect_url: (checkoutUrl || undefined) as string | undefined,
          session_id: (sessionId || undefined) as string | undefined,
        };
  }

  async verify(callbackData: Record<string, unknown>, credentials: Credentials, _ctx?: GatewayContext): Promise<VerifyResult> {
    const cb = callbackData as Record<string, unknown>;
    if (String(cb["id"] ?? '') === '') {
      return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
    }
    const apiKey = String(credentials["api_key"] ?? '');
    const res = await gwJson({
      url: `https://api.mollie.com/v2/payments/${String(encodeURIComponent(String(cb["id"] ?? cb["payment_id"])))}`,
      method: 'GET',
      headers: { ["Authorization"]: `Bearer ${String(apiKey)}` },
      timeoutMs: 10000,
    });
    const d = res.data as Record<string, unknown>;
    const amountData = ((d) as Record<string, unknown>)["amount"] ?? {};
    if (res.data === null) {
          return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
        }
    const metadata = ((d) as Record<string, unknown>)["metadata"] ?? {};
    const ok = String(((d) as Record<string, unknown>)["status"]) === String("paid");
    return {
          success: ok,
          gateway_trx_id: String(((cb) as Record<string, unknown>)["id"] ?? ''),
          amount: (String(((amountData) as Record<string, unknown>)["value"] ?? '') || null) as string | null,
          status: (ok ? 'completed' : 'failed') as VerifyResult['status'],
          trx_id: String(((metadata) as Record<string, unknown>)["trx_id"] ?? ''),
        };
  }

